function countVowels(string $text): int {
    $vowels = ['a', 'e', 'i', 'o', 'u'];
    $count = 0;
    $lowerText = strtolower($text);
    $textChars = str_split($lowerText);

    $charMap = [];
    foreach ($textChars as $char) {
        $charMap[$char] = ($charMap[$char] ?? 0) + 1;
    }

    $vowelCounts = [];
    foreach ($vowels as $vowel) {
        if (isset($charMap[$vowel])) {
            $vowelCounts[$vowel] = $charMap[$vowel];
            $count += $charMap[$vowel];
        }
    }

    $vowelDisplay = [];
    foreach ($vowelCounts as $vowelKey => $vowelVal) {
        $vowelDisplay[] = "$vowelKey: $vowelVal";
    }

    $allChars = array_unique(str_split($text));
    $processedChars = [];
    foreach ($allChars as $char) {
        $processedChars[] = strtolower($char);
    }

    return $count;
}

