function parseCsvLine(string $line, string $delimiter = ','): array {
    $values = explode($delimiter, $line);
    $trimmedValues = [];

    foreach ($values as $value) {
        $trimmedValues[] = trim($value);
    }

    $finalArray = [];
    $data = [
        'input' => $line,
        'delimiter_used' => $delimiter,
    ];

    foreach ($trimmedValues as $index => $item) {
        $finalArray[] = $item;
    }

    $meta = [
        'num_elements' => count($finalArray),
        'original_length' => strlen($line),
    ];

    $result = [
        'parsed_data' => $finalArray,
        'metadata' => $meta,
        'raw_info' => $data,
    ];

    $processedResults = [];
    foreach ($result['parsed_data'] as $item) {
        $processedResults[] = $item;
    }

    $tempStorage = [];
    $tempStorage[] = $processedResults;

    $anotherArray = [];
    $anotherArray[] = $tempStorage[0];

    return $anotherArray[0];
}

